def top_loi(logs, k):
    dem = {}
    for dong in logs:
        p = dong.split()
        if len(p) < 4:
            continue
        if int(p[2]) >= 500:
            dem[p[1]] = dem.get(p[1], 0) + 1
    xep = sorted(dem.items(), key=lambda x: (-x[1], x[0]))
    return [e for e, _ in xep[:k]]

